            long long tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }
    }
    for (int step = 2; step <= n; step <<= 1) {
        long long wlen = modPow(G, (MOD - 1) / step);
        if (dir == -1) wlen = modPow(wlen, MOD - 2);
        for (int i = 0; i < n; i += step) {
            long long w = 1;
